<?php require '../config.php';require_admin();$adminPage=true;$pageTitle='Quản lý sản phẩm';$error='';$edit=null;if(isset($_GET['delete'])){$id=(int)$_GET['delete'];try{$st=$pdo->prepare('DELETE FROM products WHERE product_id=?');$st->execute([$id]);header('Location: products.php?deleted=1');exit;}catch(PDOException $e){$error='Không thể xóa sản phẩm đã xuất hiện trong đơn hàng. Hãy giữ sản phẩm để bảo toàn lịch sử.';}}if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM products WHERE product_id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['product_id']??0);$name=trim($_POST['product_name']??'');$cat=(int)($_POST['category_id']??0);$price=(float)($_POST['price']??0);$qty=(int)($_POST['quantity']??0);$image=trim($_POST['image']??'');$desc=trim($_POST['description']??'');if($name===''||$price<0||$qty<0)$error='Vui lòng nhập dữ liệu hợp lệ.';else{if($id){$st=$pdo->prepare('UPDATE products SET category_id=?,product_name=?,price=?,quantity=?,image=?,description=? WHERE product_id=?');$st->execute([$cat?:null,$name,$price,$qty,$image,$desc,$id]);}else{$st=$pdo->prepare('INSERT INTO products(category_id,product_name,price,quantity,image,description,created_at) VALUES(?,?,?,?,?,?,NOW())');$st->execute([$cat?:null,$name,$price,$qty,$image,$desc]);}header('Location: products.php?saved=1');exit;}}$cats=$pdo->query('SELECT * FROM categories ORDER BY category_name')->fetchAll();$products=$pdo->query('SELECT p.*,c.category_name FROM products p LEFT JOIN categories c ON p.category_id=c.category_id ORDER BY p.product_id DESC')->fetchAll();require '../includes/header.php';?><div class="row g-4"><div class="col-md-3"><?php require 'nav.php';?></div><div class="col-md-9"><h1 class="section-title">Quản lý sản phẩm</h1><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><?php if(isset($_GET['saved'])): ?><div class="alert alert-success">Đã lưu sản phẩm.</div><?php endif; ?><?php if(isset($_GET['deleted'])): ?><div class="alert alert-success">Đã xóa sản phẩm.</div><?php endif; ?><form method="post" class="content-card mb-4"><h5><?= $edit?'Sửa sản phẩm':'Thêm sản phẩm' ?></h5><input type="hidden" name="product_id" value="<?= (int)($edit['product_id']??0) ?>"><div class="row g-3"><div class="col-md-6"><label class="form-label">Tên sản phẩm</label><input class="form-control" name="product_name" required value="<?= e($edit['product_name']??'') ?>"></div><div class="col-md-6"><label class="form-label">Danh mục</label><select class="form-select" name="category_id"><option value="0">Chưa phân loại</option><?php foreach($cats as $c): ?><option value="<?= $c['category_id'] ?>" <?= (int)($edit['category_id']??0)===$c['category_id']?'selected':'' ?>><?= e($c['category_name']) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Giá (VNĐ)</label><input class="form-control" type="number" min="0" step="1000" name="price" required value="<?= e($edit['price']??0) ?>"></div><div class="col-md-4"><label class="form-label">Tồn kho</label><input class="form-control" type="number" min="0" name="quantity" required value="<?= e($edit['quantity']??0) ?>"></div><div class="col-md-4"><label class="form-label">URL hình ảnh</label><input class="form-control" name="image" value="<?= e($edit['image']??'') ?>"></div><div class="col-12"><label class="form-label">Mô tả</label><textarea class="form-control" name="description" rows="2"><?= e($edit['description']??'') ?></textarea></div><div class="col-12"><button class="btn btn-red">Lưu sản phẩm</button> <?php if($edit): ?><a class="btn btn-outline-secondary" href="products.php">Hủy sửa</a><?php endif; ?></div></div></form><div class="content-card table-responsive"><table class="table table-hover"><thead><tr><th>ID</th><th>Sản phẩm</th><th>Danh mục</th><th>Giá</th><th>Kho</th><th>Thao tác</th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><?= $p['product_id'] ?></td><td><?= e($p['product_name']) ?></td><td><?= e($p['category_name']??'—') ?></td><td><?= money($p['price']) ?></td><td><?= $p['quantity'] ?></td><td class="text-nowrap"><a class="btn btn-sm btn-outline-primary" href="?edit=<?= $p['product_id'] ?>">Sửa</a> <a class="btn btn-sm btn-outline-danger" href="?delete=<?= $p['product_id'] ?>" onclick="return confirm('Bạn có chắc muốn xóa sản phẩm này?')">Xóa</a></td></tr><?php endforeach; ?></tbody></table></div></div></div><?php require '../includes/footer.php';?>
